import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Building","description":"The shared build tool, Turborepo setup, and runtime caveats","frontmatter":{"navigation":{"category":"Plugin development"},"title":"Building","description":"The shared build tool, Turborepo setup, and runtime caveats","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/building.md"},"headers":[],"relativePath":"guides/building.md","filePath":"docs/building.md","lastUpdated":1792268904000}`),a={name:`guides/building.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="building" tabindex="-1">Building <a class="header-anchor" href="#building" aria-label="Permalink to “Building”">​</a></h1><p>This guide shows you how to build a plugin, run the workspace&#39;s plugins on a local Pumpkin server, and understand the runtime limits that affect your build. The final sections explain how the shared Turborepo tasks fit together and what to check when you change <code>turbo.json</code>.</p><h2 id="build-a-plugin" tabindex="-1">Build a plugin <a class="header-anchor" href="#build-a-plugin" aria-label="Permalink to “Build a plugin”">​</a></h2><p>From the workspace root, run <code>pnpm build</code> to build every plugin package. To build one package, pass its workspace name as a filter. For example, to build AppleSkinPumpkin:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/apple-skin-pumpkin</span></span></code></pre></div><p>Both commands use <code>pumpkin-plugins-build</code> from <code>tools/build</code>. To build a <code>.wasm</code> component, set the plugin&#39;s entry file and output path in the <code>pumpkinPlugin</code> field of its <code>package.json</code>. You can also list WASI capabilities and choose an engine there:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pumpkinPlugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;entry&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;src/plugin.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;build/my-plugin.wasm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;wasi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [] }</span></span></code></pre></div><p>The engine defaults to <code>static-hermes</code>, which current plugin packages use. Set <code>&quot;engine&quot;: &quot;quickjs&quot;</code> to choose QuickJS. Both engines are supported, but they have different runtime limits; see <a href="#runtime-caveats">Runtime caveats</a> before choosing one. The <a href="/pumpkin-plugins/tools/static-hermes-runtime/README">Static Hermes Runtime guide</a> covers its toolchain and supported API calls. Development, integration, and release builds all use the engine you select.</p><p>The build tool resolves the plugin&#39;s declared <code>@pumpkin-plugins/pumpkin-api</code> dependency (including an npm alias) and reads the WIT files from the subdirectory pinned in <code>wit.lock.json</code>. That lock must match the Pumpkin server&#39;s WIT ABI. On first use, or whenever the lockfile changes, Git fetches the pinned commit into <code>.cache/pumpkin-api-wit/&lt;lock-digest&gt;/</code>; a populated cache entry can be reused without network access. Set <code>PUMPKIN_PLUGINS_CACHE_DIR</code> to put this cache elsewhere.</p><p>The tool also resolves esbuild and the selected engine. Static Hermes uses generated WASI C bindings and a component linker; the build provisions the pinned WASI SDK and <code>wit-bindgen</code> under <code>.cache/hermes/</code> when needed, then prepares Hermes automatically. QuickJS uses the Wasmtime 48 CLI fork of <code>componentize-qjs</code>. The fork is needed because the upstream Wasmtime 47 CLI can&#39;t link the WASI HTTP types used by plugins. The pinned release&#39;s own build script uses a componentizer that produces 55 MB plugins and can&#39;t run the WASI socket code.</p><p>Production builds are minified. When you build a plugin inside this repository, a component larger than 5 MiB (5,242,880 bytes) fails before the build replaces the existing <code>.wasm</code> output. If you use the published build package outside this repository, it warns above the same limit but still writes the component. Development bundles stay readable and skip the size check. Static Hermes development components optimize native code for size while retaining Hermes source locations and native line tables for backtraces.</p><h3 id="choose-build-outputs-and-options" tabindex="-1">Choose build outputs and options <a class="header-anchor" href="#choose-build-outputs-and-options" aria-label="Permalink to “Choose build outputs and options”">​</a></h3><p>Use these options when you need declarations for your editor, or when you want to try Static Hermes&#39;s TypeScript parser:</p><table tabindex="0"><thead><tr><th>Command</th><th>Result</th></tr></thead><tbody><tr><td><code>pumpkin-plugins-build</code></td><td>Writes the component to its configured output path. If the plugin declares WASI capabilities, it also writes the latest combined WIT snapshot to <code>build/wit/</code>.</td></tr><tr><td><code>pumpkin-plugins-build --types-only</code></td><td>Writes guest declarations to <code>build/types/bindings/</code> for <code>tsc</code> and your editor.</td></tr><tr><td><code>pumpkin-plugins-build --parse-ts</code></td><td>Opts Static Hermes into its partial, unstable TypeScript parser. This option isn&#39;t available with QuickJS.</td></tr></tbody></table><p>To use that parser across the repository&#39;s plugin packages, run <code>pnpm build:parse-ts</code>. For the dev server, run <code>pnpm dev -- --parse-ts</code>; it applies the option to both the initial build and watch builds.</p><p>Static Hermes uses Hades garbage collection by default. To use malloc-managed GC instead, set <code>&quot;staticHermesGc&quot;: &quot;malloc&quot;</code> in <code>pumpkinPlugin</code>. This setting only applies to Static Hermes.</p><p>Set <code>PUMPKIN_PLUGINS_VERBOSE_BUILD=1</code> to include Static Hermes tool output and show the selected <code>--wasi-imports</code>, <code>--wasi-methods</code>, <code>--api-methods</code>, and <code>--event-types</code> for each component. A root build normally hides logs for cached tasks, so pass <code>--force</code> to show the selections for every plugin:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PUMPKIN_PLUGINS_VERBOSE_BUILD</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>If a method or event filter is omitted, the build keeps all available operations or event variants.</p><h3 id="generate-and-use-typescript-declarations" tabindex="-1">Generate and use TypeScript declarations <a class="header-anchor" href="#generate-and-use-typescript-declarations" aria-label="Permalink to “Generate and use TypeScript declarations”">​</a></h3><p>Only declarations persist under <code>build/types/</code>, so <code>build</code> and <code>typecheck</code> can run in parallel without writing to the same files or retaining a second WIT tree. When a plugin requests WASI imports, its build uses a private WIT snapshot and publishes a copy to <code>build/wit/</code> for inspection. Type generation prepares WIT in a temporary directory and removes it afterward. After a fresh checkout, run <code>pnpm typecheck</code> once so your editor can find the generated types.</p><p>The shared <code>plugin-kit</code> package follows the same approach for its source: it writes declarations for filesystem imports under its ignored <code>build/types/</code> directory. The API package ships <code>wit.lock.json</code>, not a vendored WIT tree. The build command generates guest declarations from the fetched source in <code>build/types/bindings/</code>; each plugin&#39;s <code>tsconfig.json</code> includes those declarations before its source files, and keeps WIT <code>u64</code> and <code>s64</code> values typed as <code>bigint</code>.</p><p>If you&#39;re building from the published tools, the <a href="/pumpkin-plugins/tools/static-hermes-runtime/README">Static Hermes Runtime guide</a> lists the Node, pnpm, and host-tool versions used by packed consumer builds. Set <code>STATIC_HERMES_CACHE_DIR</code> to move Hermes source and build artifacts out of the default workspace cache. Run <code>pnpm run test:external-consumer</code> to pack the public tool packages and their workspace dependencies, check their public metadata and starter dependency ranges, install them from a temporary registry, and typecheck and build both generated standalone starters from a temporary consumer.</p><h2 id="run-all-plugins-on-pumpkin" tabindex="-1">Run all plugins on Pumpkin <a class="header-anchor" href="#run-all-plugins-on-pumpkin" aria-label="Permalink to “Run all plugins on Pumpkin”">​</a></h2><p>Run <code>pnpm dev</code> to build every plugin and start the latest stable Pumpkin release. To use Pumpkin&#39;s latest nightly build, run <code>pnpm dev --nightly</code> or <code>pnpm dev:nightly</code>. Stable release metadata is cached in <code>.cache/pumpkin</code> for 24 hours; set <code>PUMPKIN_REFRESH_RELEASE=1</code> to refresh it for one run. Nightly metadata refreshes at every start because the <code>nightly</code> tag is reused, and the binary cache uses the uploaded asset ID to detect replaced builds. Stable binaries are checked against <code>checksums.sha256</code>; nightly binaries are checked against their GitHub release asset SHA-256 digest.</p><p>Pass <code>--release</code> to use release settings for the initial build and hot-reload rebuilds. For example, run <code>pnpm dev -- --release</code>.</p><p>To build once and run without plugin hot reload or build watchers, run <code>pnpm dev:no-hot-reload</code>. Add <code>--nightly</code> or use <code>pnpm dev:nightly:no-hot-reload</code> to start the latest nightly build. You can also pass <code>--release</code>, as in <code>pnpm dev:no-hot-reload -- --release</code>. Restart the command after changing a plugin.</p><p>The dev server lives in <code>.cache/pumpkin-dev</code>, so its world and settings remain between runs. Each command configures Pumpkin&#39;s plugin hot reload to match the mode you chose. In hot-reload mode, <code>pnpm dev</code> watches workspace packages, rebuilds affected plugins, and copies each completed <code>.wasm</code> file into the server&#39;s <code>plugins/</code> directory. Pumpkin watches that directory, while build output lives inside each package; copying the file ensures Pumpkin sees changes because a link to the build output would not notify it when the target changes. Automatic Market update checks are disabled in the default development builds and included in <code>--release</code> builds. Plugins that request permissions still need those permissions granted on their initial load; a hot reload can&#39;t prompt for them.</p><p>To use a local server binary instead of downloading the latest release, set <code>PUMPKIN_BIN</code>. Set <code>PUMPKIN_CACHE_DIR</code> to change the binary cache directory. To reset the dev server&#39;s world, config, and plugins, stop the server and remove <code>.cache/pumpkin-dev</code>.</p><p>The build executable is <code>tools/build/dist/cli.js</code>. Turbo builds it and its Static Hermes runtime dependency before plugin builds or typechecks. If you run package commands directly after a fresh checkout, build both dependencies first:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/static-hermes-runtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>An interactive build may show a notice when a newer <code>@pumpkin-plugins/build</code> release is available on npm. Results are cached for three hours. Pass <code>--no-update-cache</code> to check npm without reading or writing the cache. The lookup is skipped for help and version commands, CI, development mode (<code>PUMPKIN_DEV_MODE=1</code>), and non-interactive output. Registry failures don&#39;t affect the build. To disable notices, use <code>--no-update-notifier</code> or set <code>PUMPKIN_PLUGINS_NO_UPDATE_NOTIFIER=1</code>. To preview a suggested migration, run this from a plugin&#39;s root:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dlx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/codemod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><h2 id="runtime-caveats" tabindex="-1">Runtime caveats <a class="header-anchor" href="#runtime-caveats" aria-label="Permalink to “Runtime caveats”">​</a></h2><h3 id="quickjs-runtime" tabindex="-1">QuickJS runtime <a class="header-anchor" href="#quickjs-runtime" aria-label="Permalink to “QuickJS runtime”">​</a></h3><p>QuickJS plugins run inside the server&#39;s WebAssembly runtime, which has a few limits to account for:</p><ul><li>There is no global <code>TextEncoder</code>, <code>TextDecoder</code>, or <code>fetch</code>. Use <code>fflate</code>&#39;s <code>strToU8</code> and <code>strFromU8</code> for text encoding. If your plugin needs HTTP, import <code>wasi:http</code> by declaring the <code>http</code> capability; the update-check tool is one example.</li><li>WIT <code>u64</code> and <code>s64</code> values are JavaScript <code>bigint</code> in both directions. Keep the generated <code>bigint</code> types, and convert to <code>number</code> only when the value is within JavaScript&#39;s safe integer range.</li><li>Scheduler delays and periods are <code>u64</code> (<code>bigint</code>); handler and task IDs are <code>u32</code> (<code>number</code>). The plugin-kit scheduler helpers accept safe integer tick counts and pass them as <code>BigInt</code>.</li><li>The first time a plugin requests permissions, the server prompts for them in its console. A hot reload can&#39;t show that prompt and denies the permissions, so restart the server for the first load.</li><li>Two builds of the same source produce different bytes. If you sign or upload a build, use the artifact from the build job instead of rebuilding it.</li></ul><h3 id="static-hermes" tabindex="-1">Static Hermes <a class="header-anchor" href="#static-hermes" aria-label="Permalink to “Static Hermes”">​</a></h3><p>Static Hermes plugins use the WASI 2 C API path in <code>tools/static-hermes-runtime</code>. Its native JSI shim implements only part of the Pumpkin API. The runtime reads the prepared WIT directory from <code>@pumpkin-plugins/build</code>, which owns the WASI version and WIT files. It validates every operation in an imported WASI interface, including operations your plugin doesn&#39;t use, and generates native adapters for operations selected by build analysis. The imported WASI 0.2.3 operations cover filesystem, HTTP, streams, clocks, TCP, UDP, and sockets. Selecting a feature-gated operation also enables its WIT feature. Event converters keep complete payload fields for statically registered event types; dynamic or unresolved registrations retain every event case and payload field. Static Hermes development builds disable the shared automatic update check. WASI 3 support is deferred.</p><h2 id="turborepo" tabindex="-1">Turborepo <a class="header-anchor" href="#turborepo" aria-label="Permalink to “Turborepo”">​</a></h2><p>Turborepo defines the workspace task graph in <code>turbo.json</code>; the root scripts run those tasks. The main commands are <code>pnpm build</code>, <code>pnpm typecheck</code>, <code>pnpm test</code>, <code>pnpm test:integration</code>, <code>pnpm readme</code>, and <code>pnpm package</code>. The <a href="/pumpkin-plugins/guides/turborepo">Turborepo commands guide</a> explains the <code>pnpm turbo</code> wrapper, its log defaults, and how to override them.</p><p>These are the tasks and outputs Turbo caches:</p><table tabindex="0"><thead><tr><th>Task</th><th>What it does or caches</th></tr></thead><tbody><tr><td><code>transit</code></td><td>Does no work itself; carries the hashes of a package&#39;s dependencies so their changes invalidate dependent tasks.</td></tr><tr><td><code>build</code></td><td>Caches <code>build/**</code> except <code>build/types/**</code>, plus package <code>dist/**</code> output.</td></tr><tr><td><code>benchmark:build</code></td><td>Caches the engine-comparison components and stack-guard fixtures, with a separate output path for each configuration.</td></tr><tr><td><code>typecheck</code></td><td>Caches generated <code>build/types/**</code> declarations and restores them on a cache hit.</td></tr><tr><td><code>test</code></td><td>Caches <code>dist/**</code> for the <code>static-hermes-runtime</code> package&#39;s test build.</td></tr><tr><td><code>test:integration</code></td><td>Depends on <code>build</code> and is never cached because it starts a real server.</td></tr><tr><td><code>readme</code>, <code>readme:check</code></td><td>Never cached because they write or inspect files.</td></tr></tbody></table><p>The build tool, signing tool, plugin creator, and test harness <code>typecheck</code> tasks run <code>tsc --noEmit</code>, so their package-level Turbo configurations declare no outputs. Plugin typechecks keep the root <code>build/types/**</code> outputs because they generate the guest declarations that builds and editors need.</p><p>The <code>@pumpkin-plugins/build</code> build and test tasks also build <code>@pumpkin-plugins/static-hermes-runtime</code> and <code>@pumpkin-plugins/wasi-capabilities</code> first. The build tool imports their compiled package entries, so both public tools declare their <code>dist/**</code> output for Turbo to restore when those builds come from cache.</p><p>Run <code>pnpm clean</code> to remove workspace <code>node_modules</code>, root and workspace <code>build/</code> and <code>dist/</code> output, and <code>.turbo/cache/</code>. It preserves <code>.cache/</code>.</p><p>When you run <code>pnpm build</code>, Turbo checks the selected task graph and prepares Static Hermes once before plugin builds start. A QuickJS-only filter skips that setup. Direct package builds still prepare Hermes when needed.</p><h3 id="when-you-change-turbo-json" tabindex="-1">When you change <code>turbo.json</code> <a class="header-anchor" href="#when-you-change-turbo-json" aria-label="Permalink to “When you change turbo.json”">​</a></h3><h4 id="keep-cache-keys-tied-to-dependencies" tabindex="-1">Keep cache keys tied to dependencies <a class="header-anchor" href="#keep-cache-keys-tied-to-dependencies" aria-label="Permalink to “Keep cache keys tied to dependencies”">​</a></h4><p>Most workspace packages are used as source because their <code>exports</code> point at <code>src/</code>; nothing is built before a dependent task runs, so Turborepo has no reason to look at a dependency&#39;s files. The public <code>@pumpkin-plugins/wasi-capabilities</code> package is compiled to <code>dist/</code> so Node can load it from <code>node_modules</code>, and its build runs before dependent package tasks.</p><p>The <code>transit</code> task is Turborepo&#39;s &quot;transit nodes&quot; pattern. It has no script and depends on <code>^transit</code>. The <code>build</code>, <code>typecheck</code>, and <code>test</code> tasks depend on it, so changes in a package&#39;s dependencies invalidate exactly the affected tasks. This includes <code>devDependencies</code> such as <code>tools/build</code>, whose <code>wasi-wit.lock.json</code> and <code>src/</code> determine what a plugin is built from. You don&#39;t need to add new tools to a central list as long as a plugin declares them in its <code>package.json</code>.</p><p>Use <code>globalDependencies</code> only for inputs outside packages: <code>.node-version</code> (the Node version CI selects; Turborepo doesn&#39;t hash <code>process.version</code>), <code>tsconfig.base.json</code>, and <code>pnpm-workspace.yaml</code> (which pins the API package and ABI). The lockfile and root <code>package.json</code> invalidate everything. The packages that the root <code>package.json</code> depends on (<code>tools/docs</code> and <code>tools/signing</code>) also invalidate everything because Turborepo treats them as global.</p><h4 id="pass-task-environment-variables-explicitly" tabindex="-1">Pass task environment variables explicitly <a class="header-anchor" href="#pass-task-environment-variables-explicitly" aria-label="Permalink to “Pass task environment variables explicitly”">​</a></h4><p>Turborepo uses strict environment mode, so tasks only receive variables you declare. The <code>PUMPKIN_*</code> variables read by the test harness and build download cache are in <code>globalPassThroughEnv</code>. They don&#39;t affect cache keys because they only choose locations or affect uncached tasks. <code>TMPDIR</code> isn&#39;t passed through, so tests run by Turbo create temporary directories under <code>/tmp</code>.</p><p>Static Hermes toolchain paths pass through to the uncached <code>test:integration</code> task. Integration fixtures can build plugins, so they should reuse the toolchain already prepared in CI.</p><h4 id="declare-task-dependencies-carefully" tabindex="-1">Declare task dependencies carefully <a class="header-anchor" href="#declare-task-dependencies-carefully" aria-label="Permalink to “Declare task dependencies carefully”">​</a></h4><p>The root package defines a <code>build</code> script (<code>&quot;build&quot;: &quot;node scripts/build.mjs&quot;</code>), so adding <code>dependsOn: [&quot;^build&quot;]</code> would make the root package a dependency of itself and fail or loop. The <code>transit</code> task can use <code>^transit</code> because the root package doesn&#39;t have a <code>transit</code> script. Don&#39;t add a root script with that name. See Turborepo&#39;s &quot;Missing root task in turbo.json&quot; documentation.</p><h4 id="keep-simple-checks-outside-turborepo" tabindex="-1">Keep simple checks outside Turborepo <a class="header-anchor" href="#keep-simple-checks-outside-turborepo" aria-label="Permalink to “Keep simple checks outside Turborepo”">​</a></h4><p><code>pnpm lint</code> runs Biome and ESLint directly. Both are fast, so caching them wouldn&#39;t save much.</p><h4 id="preserve-repository-settings" tabindex="-1">Preserve repository settings <a class="header-anchor" href="#preserve-repository-settings" aria-label="Permalink to “Preserve repository settings”">​</a></h4><p>Keep <code>&quot;agentGuidance&quot;: false</code>. Otherwise, Turborepo writes an <code>AGENTS.md</code> when it detects an AI agent and adds it again if deleted.</p><p>The package manager version is declared with <code>devEngines.packageManager</code> in the root <code>package.json</code>; Turborepo, pnpm, and <code>pnpm/action-setup</code> all read it.</p><p>Remote caching isn&#39;t configured. CI caches <code>.turbo</code> with <code>actions/cache</code>. To use a remote cache, set <code>TURBO_TOKEN</code> and <code>TURBO_TEAM</code>.</p><p>For details about the exact installed Turborepo version, read the <code>docs/</code> directory inside the <code>turbo</code> package. From the repository root, locate that package with:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;require(&#39;path&#39;).dirname(require.resolve(&#39;turbo/package.json&#39;))&quot;</span></span></code></pre></div>`,65)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};